      async calculateAndSaveDailyStats(branchId, date) {
        const startOfDay = new Date(date);
        startOfDay.setHours(0, 0, 0, 0);
        const endOfDay = new Date(date);
        endOfDay.setHours(23, 59, 59, 999);
        const dayTickets = await db.select().from(tickets).where(and(
          eq(tickets.branchId, branchId),
          gte(tickets.joinedAt, startOfDay),
          lte(tickets.joinedAt, endOfDay)
        ));
        const served = dayTickets.filter((t) => t.status === "completed").length;
        const noShow = dayTickets.filter((t) => t.status === "no_show").length;
        const cancelled = dayTickets.filter((t) => t.status === "cancelled").length;
        const completedWithWait = dayTickets.filter((t) => t.actualWaitTime !== null);
        const avgWaitTime = completedWithWait.length > 0 ? Math.round(completedWithWait.reduce((sum, t) => sum + (t.actualWaitTime || 0), 0) / completedWithWait.length) : 0;
        const completedWithService = dayTickets.filter((t) => t.serviceTime !== null);
        const avgServiceTime = completedWithService.length > 0 ? Math.round(completedWithService.reduce((sum, t) => sum + (t.serviceTime || 0), 0) / completedWithService.length) : 0;
        const existing = await this.getDailyStats(branchId, date);
        const data = {
          branchId,
          date: startOfDay,
          totalServed: served,
          totalNoShow: noShow,
          totalCancelled: cancelled,
          avgWaitTime,
          avgServiceTime,
          updatedAt: /* @__PURE__ */ new Date()
        };
        if (existing) {
          const [stat2] = await db.update(dailyStats).set(data).where(eq(dailyStats.id, existing.id)).returning();
          return stat2;
        }
        const [stat] = await db.insert(dailyStats).values(data).returning();
        return stat;
      }
