      async getQueueStats(branchId, serviceId) {
        const today = /* @__PURE__ */ new Date();
        today.setHours(0, 0, 0, 0);
        const tomorrow = new Date(today);
        tomorrow.setDate(tomorrow.getDate() + 1);
        const conditions = [
          eq(tickets.branchId, branchId),
          gte(tickets.joinedAt, today),
          lt(tickets.joinedAt, tomorrow)
        ];
        if (serviceId) conditions.push(eq(tickets.serviceId, serviceId));
        const dayTickets = await db.select().from(tickets).where(and(...conditions));
        const completed = dayTickets.filter((t) => t.status === "completed" || t.status === "arrived");
        const todayServed = completed.length;
        const todayWaiting = dayTickets.filter((t) => ["waiting", "called", "serving"].includes(t.status)).length;
        const todayNoShow = dayTickets.filter((t) => t.status === "no_show").length;
        const waitSamples = completed.map((t) => {
          if (t.calledAt && t.joinedAt) {
            return (new Date(t.calledAt).getTime() - new Date(t.joinedAt).getTime()) / 6e4;
          }
          return null;
        }).filter((v) => v !== null && v >= 0);
        const waitSampleSum = waitSamples.reduce((a, b) => a + b, 0);
        const averageWaitTime = waitSamples.length > 0 ? Math.round(waitSampleSum / waitSamples.length * 10) / 10 : 0;
        const serviceSamples = completed.map((t) => {
          if (t.completedAt && (t.servedAt || t.calledAt)) {
            const ref = t.servedAt || t.calledAt;
            return (new Date(t.completedAt).getTime() - new Date(ref).getTime()) / 6e4;
          }
          return null;
        }).filter((v) => v !== null && v >= 0);
        const serviceSampleSum = serviceSamples.reduce((a, b) => a + b, 0);
        const averageServiceTime = serviceSamples.length > 0 ? Math.round(serviceSampleSum / serviceSamples.length * 10) / 10 : 0;
        return {
          todayServed,
          todayWaiting,
          todayNoShow,
          averageWaitTime,
          averageServiceTime,
          waitSampleCount: waitSamples.length,
          waitSampleSum,
          serviceSampleCount: serviceSamples.length,
          serviceSampleSum
        };
      }
