async function processIncomingWhatsApp(from, messageBody) {
  const refCodeMatch = messageBody.match(/(?:TIQKET\s*ID:\s*)?(TQ[A-Z0-9]{5})/);
  if (!refCodeMatch) {
    await sendWhatsAppMessage(
      from,
      `Hi! We couldn't find a valid reference code in your message.

Please send the exact reference code you received after joining the queue (e.g., TQ3AB7K).

If you haven't joined a queue yet, scan the QR code at the location to get started.`
    );
    return;
  }
  const refCode = refCodeMatch[1];
  try {
    const [ticket] = await db.select().from(tickets).where(eq4(tickets.whatsappRefCode, refCode)).limit(1);
    if (!ticket) {
      await sendWhatsAppMessage(
        from,
        `Sorry, the reference code *${refCode}* was not found. It may have expired or been entered incorrectly.

Please check the code and try again, or scan the QR code to join a new queue.`
      );
      return;
    }
    const existingBranch = ticket.branchId ? await db.select().from(branches).where(eq4(branches.id, ticket.branchId)).limit(1).then((r) => r[0]) : null;
    const branchNameForStatus = existingBranch?.name || "the venue";
    const status = String(ticket.status || "").toLowerCase();
    const customerLabel = ticket.customerName ? ticket.customerName : "there";
    const tn = ticket.ticketNumber;
    if (status === "completed" || status === "served") {
      await sendWhatsAppMessage(
        from,
        `Hi ${customerLabel}, your ticket *${tn}* at *${branchNameForStatus}* has already been serviced. Thank you for visiting!

If you need to join again, please scan the QR code at the venue.`
      );
      return;
    }
    if (status === "no_show") {
      await sendWhatsAppMessage(
        from,
        `Hi ${customerLabel}, ticket *${tn}* was marked as no-show and is no longer active.

Please scan the QR code at *${branchNameForStatus}* to register again.`
      );
      return;
    }
    if (status === "cancelled" || status === "canceled") {
      await sendWhatsAppMessage(
        from,
        `Hi ${customerLabel}, ticket *${tn}* was cancelled and is no longer active.

Please scan the QR code at *${branchNameForStatus}* to register again.`
      );
      return;
    }
    if (status === "serving") {
      const deskLine = ticket.deskName ? `
Desk: *${ticket.deskName}*` : "";
      await sendWhatsAppMessage(
        from,
        `Hi ${customerLabel}, your ticket *${tn}* is currently being served at *${branchNameForStatus}*.${deskLine}

Please proceed to the counter if you haven't already.`
      );
      return;
    }
    if (status === "hold") {
      await sendWhatsAppMessage(
        from,
        `Hi ${customerLabel}, your ticket *${tn}* at *${branchNameForStatus}* is currently on hold.

Please contact the front desk to resume your booking.`
      );
      return;
    }
    if (ticket.whatsappConfirmed) {
      const positionLine = typeof ticket.position === "number" && ticket.position > 0 ? `
Position: *#${ticket.position}*` : "";
      const waitLine = typeof ticket.estimatedWaitTime === "number" && ticket.estimatedWaitTime > 0 ? `
Estimated wait: ~${ticket.estimatedWaitTime} min` : "";
      const serviceLine = ticket.serviceName ? `
Service: ${ticket.serviceName}` : "";
      await sendWhatsAppMessage(
        from,
        `Hi ${customerLabel}, you're already in the queue at *${branchNameForStatus}*.

Ticket: *${tn}*${serviceLine}${positionLine}${waitLine}

We'll notify you on WhatsApp when it's your turn. There's no need to register again.`
      );
      return;
    }
    if (status !== "waiting") {
      await sendWhatsAppMessage(
        from,
        `Hi ${customerLabel}, ticket *${tn}* is no longer active (status: ${ticket.status}).

Please scan the QR code at *${branchNameForStatus}* to register again.`
      );
      return;
    }
    const cleanPhone = from.replace(/[^0-9]/g, "");
    await db.update(tickets).set({
      whatsappConfirmed: true,
      whatsappPhone: cleanPhone,
      customerPhone: ticket.customerPhone || cleanPhone,
      updatedAt: /* @__PURE__ */ new Date()
    }).where(eq4(tickets.id, ticket.id));
    const branch = ticket.branchId ? await db.select().from(branches).where(eq4(branches.id, ticket.branchId)).limit(1).then((r) => r[0]) : null;
    const branchName = branch?.name || "Queue";
    const queueMode = branch?.queueMode || "fifo";
    const mode = normalizeWaMode(queueMode);
    const guestCount = ticket.formData?.partySize || ticket.formData?.guests || "";
    const formData = ticket.formData || {};
    const baseVars = {
      customer_name: ticket.customerName || "",
      ticket_number: ticket.ticketNumber,
      service_name: ticket.serviceName || "",
      branch_name: branchName,
      restaurant_name: branchName,
      foodcourt_name: branchName,
      booking_id: ticket.ticketNumber,
      order_id: ticket.ticketNumber,
      queue_position: ticket.position ?? "",
      wait_time: ticket.estimatedWaitTime ?? "",
      guest_count: guestCount,
      appointment_time: formData.appointmentTime || formData.time || "",
      appointment_date: formData.appointmentDate || formData.date || "",
      staff_name: formData.staffName || ""
    };
    let replyKey = "joined";
    if (mode === "dinein") replyKey = "confirmed";
    else if (mode === "takeaway") replyKey = "confirmed";
    else if (mode === "checkin") replyKey = "confirmed";
    const replyBody = await renderWaMessage(mode, replyKey, "en", baseVars);
    if (replyBody) await sendWhatsAppMessage(from, replyBody);
    console.log(
      `WhatsApp confirmed: ticket ${ticket.ticketNumber}, phone ${cleanPhone}, ref ${refCode}`
    );
  } catch (error) {
    console.error("Error processing WhatsApp reference:", error);
    await sendWhatsAppMessage(
      from,
      `Something went wrong while confirming your registration. Please try again in a moment.`
    );
  }
}
async function buildTicketVars(ticketRow, branchName) {
  const branch = ticketRow.branchId ? await db.select().from(branches).where(eq4(branches.id, ticketRow.branchId)).limit(1).then((r) => r[0]) : null;
  const mode = normalizeWaMode(branch?.queueMode || "fifo");
  const formData = ticketRow.formData || {};
  const guestCount = formData.partySize || formData.guests || "";
  const vars = {
    customer_name: ticketRow.customerName || "",
    ticket_number: ticketRow.ticketNumber,
    service_name: ticketRow.serviceName || "",
    branch_name: branchName,
    restaurant_name: branchName,
    foodcourt_name: branchName,
    booking_id: ticketRow.ticketNumber,
    order_id: ticketRow.ticketNumber,
    queue_position: ticketRow.position ?? "",
    wait_time: ticketRow.estimatedWaitTime ?? "",
    counter_no: ticketRow.deskName || "",
    pickup_counter: ticketRow.deskName || "",
    guest_count: guestCount,
    // Optional fields the multistage / checkin / dinein templates can ask for.
    // Pulled from the booking form payload so they survive across the whole
    // ticket lifecycle without extra DB lookups.
    appointment_time: formData.appointmentTime || formData.time || "",
    appointment_date: formData.appointmentDate || formData.date || "",
    reservation_time: formData.reservationTime || formData.time || "",
    staff_name: formData.staffName || "",
    stage_name: ticketRow.currentStageName || formData.stageName || "",
    table_no: formData.tableNumber || ""
  };
  return { mode, vars };
}
function formatReservationTime(reservationTime, formData) {
  if (formData?.reservationTime && typeof formData.reservationTime === "string") return formData.reservationTime;
  if (formData?.time) return String(formData.time);
  if (reservationTime) {
    return new Date(reservationTime).toLocaleString("en-IN", {
      dateStyle: "medium",
      timeStyle: "short",
      timeZone: "Asia/Kolkata"
    });
  }
  return "";
}
