  const usedLearnedData = input.emaServiceMs != null && input.emaServiceMs > 0;
  const serviceMs = usedLearnedData ? input.emaServiceMs : Math.max(1, input.fallbackServiceMinutes) * 6e4;
  const ahead = Math.max(0, input.position - 1);
